    // Thread safe. This function can be disabled with `outputStateIdToStringFunction` setting.
    public static stateIdToString(id: StateId): string 
    {
        switch (id)
        {
            case StateId.ROOT: return "ROOT";
            case StateId.MANETTA: return "MANETTA";
            case StateId.FAULT: return "FAULT";
            case StateId.OFF: return "OFF";
            case StateId.ON: return "ON";
            case StateId.BREWING: return "BREWING";
            case StateId.IDLE: return "IDLE";
            case StateId.STEAM: return "STEAM";
            case StateId.STEAM_HEATING: return "STEAM_HEATING";
            case StateId.STEAM_READY: return "STEAM_READY";
            default: return "?";
        }
    }
    
